<section class="page-heading"><p class="eyebrow">RIDE COORDINATION</p><h1>Messages.</h1><p>Coordinate with confirmed riders. Messages are stored in MySQL; updates are not real-time.</p></section>
<div class="chat-layout"><aside class="conversation-list"><h2>Conversations</h2><?php if(!$data['conversations']): ?><p class="muted p-3">Confirmed ride conversations will appear here.</p><?php endif; ?><?php foreach($data['conversations'] as $conversation): ?><a class="conversation-link <?= ($data['chosen']??0)==$conversation['booking_id']?'selected':'' ?>" href="index.php?page=chat&booking=<?= (int)$conversation['booking_id'] ?>"><span class="avatar"><?= e(strtoupper(substr($conversation['other_name'],0,1))) ?></span><span><strong><?= e($conversation['other_name']) ?></strong><small><?= e($conversation['origin']) ?> → <?= e($conversation['destination']) ?></small></span><?php if((int)$conversation['unread_count']>0): ?><span class="unread-count" aria-label="<?= (int)$conversation['unread_count'] ?> unread messages"><?= (int)$conversation['unread_count'] ?></span><?php endif; ?></a><?php endforeach; ?></aside><section class="chat-thread"><div class="thread-head"><strong><?= !empty($data['chosen']) ? 'Ride conversation' : 'Select a conversation' ?></strong><small>Messages are checked when you open this screen.</small></div><?php if(isset($data['messages'])): ?><div class="messages-list" id="messages-list"><?php foreach($data['messages'] as $message): ?><div class="message <?= (int)$message['sender_id']===(int)current_user()['id']?'mine':'' ?>"><small><?= e($message['sender_name']) ?> · <?= e(date('M j, g:i a',strtotime($message['created_at']))) ?></small><p><?= nl2br(e($message['body'])) ?></p></div><?php endforeach; ?></div><form method="post" class="message-compose"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="message"><input type="hidden" name="return_page" value="chat"><input type="hidden" name="booking_id" value="<?= (int)$data['chosen'] ?>"><label class="visually-hidden" for="body">Message</label><input class="form-control" id="body" name="body" maxlength="2000" required placeholder="Write a message…"><button class="btn btn-primary" aria-label="Send message">Send <span aria-hidden="true">→</span></button></form><?php else: ?><div class="empty-chat"><span>↗</span><p>Choose a ride conversation to start coordinating.</p></div><?php endif; ?></section></div>